{
  "name": "共享串口同步组件",
  "name_en": "Shared Serial Synchronization Helper",
  "manufacturer": "",
  "description": "用于实验设备通信的非物理软件组件。它为串口对象提供加锁与同步访问能力，并封装常见的串口读写操作，以便多个上层设备模块安全地共享同一串口连接。",
  "description_en": "A non-physical software component used in laboratory device communication. It provides locking and synchronized access around a serial object and exposes common serial read/write operations so multiple higher-level device modules can safely share the same serial connection.",
  "actions": [
    {
      "action_name": "auto-lock",
      "description": "锁定共享串口访问",
      "description_en": "lock access to the shared serial connection"
    },
    {
      "action_name": "auto-readline",
      "description": "从共享串口读取一行数据",
      "description_en": "read one line from the shared serial connection"
    },
    {
      "action_name": "auto-readlines",
      "description": "从共享串口读取多行数据",
      "description_en": "read multiple lines from the shared serial connection"
    },
    {
      "action_name": "auto-read_until",
      "description": "从共享串口读取直到终止符",
      "description_en": "read from the shared serial connection until a terminator is reached"
    },
    {
      "action_name": "auto-write",
      "description": "向共享串口写入数据",
      "description_en": "write data to the shared serial connection"
    }
  ],
  "tag_hints": [
    "shared serial connection",
    "serial synchronization",
    "thread-safe serial access",
    "pySerial utility",
    "instrument communication helper"
  ]
}

